using System.Net;
using System.Collections.ObjectModel;
using System.Text.Json;

namespace V2rayNMonitor.Core;

/// <summary>Verifies the routed AnyTLS proxy generated by fqfqgo/v2rayN 95f68d9; credentials stay in memory.</summary>
public static class SingboxParser
{
    public const string ClientVersion = "7.25.1+95f68d9955c2324518c5e1dc9485d73412102a95";

    public static bool HasAnyTlsProxy(ReadOnlyMemory<byte> json)
    {
        try
        {
            using var doc = JsonDocument.Parse(json);
            var outbounds = Read(doc.RootElement, "outbounds");
            return outbounds.ValueKind == JsonValueKind.Array
                && outbounds.EnumerateArray().Any(x => Text(x, "tag") == "proxy" && Text(x, "type") == "anytls");
        }
        catch (JsonException) { return false; }
    }

    public static bool TryReadConfiguration(ReadOnlyMemory<byte> json, ReadOnlyMemory<byte> statisticsJson,
        out XrayEffectiveConfiguration? configuration, out string reason)
    {
        configuration = null;
        reason = "unsupported_mode";
        try
        {
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            if (!UniqueKeys(root)) return false;
            var outbounds = Read(root, "outbounds");
            if (outbounds.ValueKind != JsonValueKind.Array || !Empty(Read(root, "endpoints"))) return false;
            var entries = outbounds.EnumerateArray().ToArray();
            var proxies = entries.Where(x => Text(x, "tag") == "proxy").ToArray();
            if (proxies.Length != 1 || Text(proxies[0], "type") != "anytls"
                || entries.Any(x => Text(x, "tag").Length == 0 || Text(x, "type").Length == 0)
                || entries.Select(x => Text(x, "tag")).Distinct(StringComparer.Ordinal).Count() != entries.Length
                || !Empty(Read(proxies[0], "detour"))) return false;
            var inbounds = Read(root, "inbounds");
            if (inbounds.ValueKind == JsonValueKind.Array && inbounds.EnumerateArray().Any(x => Text(x, "type") == "tun")) return false;
            if (!Empty(Read(Read(root, "experimental"), "v2ray_api"))) return false;
            var proxy = proxies[0];
            var address = Text(proxy, "server");
            var port = Read(proxy, "server_port");
            if (address.Length == 0 || !port.TryGetInt32(out var number) || number is < 1 or > 65535
                || Text(proxy, "password").Length == 0) return false;
            reason = "invalid_statistics_configuration";
            if (!TryReadStatisticsEndpoint(statisticsJson, out var endpoint)) return false;
            // The approved core counts the route-matched tag. A group selecting proxy is
            // still outside this counter; extra outbounds cannot broaden its attribution.
            var uncollected = entries.Where(x => Text(x, "tag") != "proxy"
                && Text(x, "type") is not ("direct" or "block" or "dns")).ToArray();
            var scope = new ProxyCollectionScope(uncollected.Length,
                uncollected.Count(x => Text(x, "type") is "selector" or "urltest"));
            configuration = new(endpoint!, "anytls",
                XrayParser.ServerIdentity("anytls", address, number, "", Text(proxy, "password")), "sing-box", scope);
            reason = "ready";
            return true;
        }
        catch (Exception e) when (e is JsonException or InvalidOperationException or FormatException) { return false; }
    }

    public static bool TryReadStatisticsEndpoint(ReadOnlyMemory<byte> json, out Uri? endpoint)
    {
        endpoint = null;
        if (json.Length is <= 0 or > 4096) return false;
        try
        {
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return false;
            var fields = root.EnumerateObject().ToArray();
            if (fields.Length != 1 || fields[0].Name != "listen" || fields[0].Value.ValueKind != JsonValueKind.String) return false;
            var listen = fields[0].Value.GetString()!;
            if (!IPEndPoint.TryParse(listen, out var parsed) || !IPAddress.IsLoopback(parsed.Address) || parsed.Port == 0
                || !Uri.TryCreate("http://" + listen, UriKind.Absolute, out var uri)
                || uri.Port != parsed.Port || uri.AbsolutePath != "/" || uri.Query.Length != 0
                || uri.Fragment.Length != 0 || uri.UserInfo.Length != 0) return false;
            endpoint = uri;
            return true;
        }
        catch (JsonException) { return false; }
    }

    /// <summary>
    /// Projects candidates from a configuration bound to an already verified routed-proxy snapshot.
    /// This does not verify a running core, enable collection, or map other members to subscriptions.
    /// </summary>
    public static bool TryReadMemberCatalog(XraySnapshot snapshot, ReadOnlyMemory<byte> configurationJson,
        out SingboxMemberCatalog? catalog, out string reason)
    {
        catalog = null;
        reason = "snapshot_changed";
        if (snapshot.CoreName != "sing-box" || string.IsNullOrEmpty(snapshot.InstanceId)
            || !snapshot.Generation.StartsWith(XrayParser.Hash(configurationJson.Span) + ":", StringComparison.Ordinal)) return false;
        reason = "unsupported_configuration";
        try
        {
            using var doc = JsonDocument.Parse(configurationJson);
            var root = doc.RootElement;
            if (!UniqueKeys(root) || !Empty(Read(root, "endpoints"))) return false;
            var inbounds = Read(root, "inbounds");
            if (inbounds.ValueKind == JsonValueKind.Array && inbounds.EnumerateArray().Any(x => Text(x, "type") == "tun")) return false;
            var outbounds = Read(root, "outbounds");
            if (outbounds.ValueKind != JsonValueKind.Array) return false;
            var entries = outbounds.EnumerateArray().ToArray();
            if (entries.Any(x => Text(x, "tag").Length == 0 || Text(x, "type").Length == 0)
                || entries.Select(x => Text(x, "tag")).Distinct(StringComparer.Ordinal).Count() != entries.Length) return false;
            var candidates = new Dictionary<string, SingboxMemberIdentity>(StringComparer.Ordinal);
            var unavailable = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var entry in entries)
            {
                var tag = Text(entry, "tag");
                var type = Text(entry, "type");
                var unavailableReason = tag.Contains(">>>", StringComparison.Ordinal) ? "invalid_statistics_tag"
                    : !Empty(Read(entry, "detour")) ? "dependent_outbound"
                    : type is "selector" or "urltest" ? "group_not_member"
                    : type == "direct" ? "excluded_outbound"
                    : type is not ("socks" or "http" or "shadowsocks" or "vmess" or "vless" or "trojan" or "anytls" or "hysteria2" or "tuic")
                        ? "unsupported_member_type" : null;
                if (unavailableReason is not null) unavailable.Add(tag, unavailableReason);
                else candidates.Add(tag, new(tag, type, tag == "proxy" && type == "anytls"
                    && !string.IsNullOrEmpty(snapshot.NodeId) ? snapshot.NodeId : null));
            }
            catalog = new(snapshot.InstanceId, snapshot.Generation, snapshot.ProcessIdentity,
                new ReadOnlyDictionary<string, SingboxMemberIdentity>(candidates),
                new ReadOnlyDictionary<string, string>(unavailable));
            reason = "ready";
            return true;
        }
        catch (Exception e) when (e is JsonException or InvalidOperationException or FormatException) { return false; }
    }

    public static bool MatchesSelectedConnection(IReadOnlyDictionary<string, string?> profile,
        ReadOnlyMemory<byte> guiJson, ReadOnlyMemory<byte> configurationJson, out string reason)
    {
        reason = "mapping_changed";
        try
        {
            string P(string key) => profile.TryGetValue(key, out var value) ? value ?? "" : "";
            using var gui = JsonDocument.Parse(guiJson);
            using var doc = JsonDocument.Parse(configurationJson);
            using var transport = JsonDocument.Parse(string.IsNullOrWhiteSpace(P("TransportExtra")) ? "{}" : P("TransportExtra"));
            if (!UniqueKeys(doc.RootElement) || !UniqueKeys(gui.RootElement) || !UniqueKeys(transport.RootElement)) return false;
            var proxy = Read(doc.RootElement, "outbounds").EnumerateArray().Single(x => Text(x, "tag") == "proxy");
            var tls = Read(proxy, "tls");
            var defaults = Read(gui.RootElement, "CoreBasicItem");
            // These branches need their own generator equivalence checks before collecting.
            if (P("StreamSecurity") != "tls" || !string.IsNullOrWhiteSpace(P("Cert"))
                || !string.IsNullOrWhiteSpace(P("EchConfigList"))
                || !Empty(Read(proxy, "transport")) || !Empty(Read(proxy, "multiplex"))
                || proxy.EnumerateObject().Any(x => x.Name is not ("tag" or "type" or "server" or "server_port"
                    or "password" or "tls" or "bind_interface" or "inet4_bind_address")))
            { reason = "unsupported_connection"; return false; }
            var allowedTls = new[] { "enabled", "server_name", "insecure", "alpn", "utls", "fragment", "record_fragment", "certificate_public_key_sha256" };
            if (tls.ValueKind != JsonValueKind.Object || tls.EnumerateObject().Any(x => !allowedTls.Contains(x.Name, StringComparer.Ordinal)))
            { reason = "unsupported_connection"; return false; }
            var trans = transport.RootElement;
            var network = P("Network") is "raw" or "ws" or "httpupgrade" or "xhttp" or "grpc" or "kcp" ? P("Network") : "raw";
            var host = network == "grpc" ? Text(trans, "GrpcAuthority")
                : network is "" or "raw" or "ws" or "httpupgrade" or "xhttp" ? Text(trans, "Host") : "";
            var sni = P("Sni").Length != 0 ? P("Sni") : List(host).FirstOrDefault() ?? "";
            if (!Flag(tls, "enabled") || Text(tls, "server_name") != sni
                || !SameList(Read(tls, "alpn"), List(P("Alpn")))) return false;
            var fingerprint = P("Fingerprint");
            var utls = Read(tls, "utls");
            if (fingerprint.Length == 0)
            {
                if (!Empty(utls)) return false; // The fixed client does not emit DefFingerprint when absent.
            }
            else if (!Flag(utls, "enabled") || Text(utls, "fingerprint") != fingerprint
                || utls.EnumerateObject().Any(x => x.Name is not ("enabled" or "fingerprint"))) return false;
            var pins = new List<string>();
            foreach (var part in List(P("CertSha")))
            {
                var hex = part.Replace(":", "").Replace(" ", "");
                if (hex.Length == 64 && hex.All(char.IsAsciiHexDigit)) continue; // Client discards Xray-style hex pins.
                try { if (Convert.FromBase64String(part).Length == 32) pins.Add(part); }
                catch (FormatException) { } // Same generator rule: invalid pins are discarded.
            }
            if (!SameList(Read(tls, "certificate_public_key_sha256"), pins)
                || Flag(tls, "insecure") != (pins.Count == 0 && P("AllowInsecure") == "true")) return false;
            var fragment = Flag(defaults, "EnableFragment");
            if (Flag(tls, "fragment") != fragment || Flag(tls, "record_fragment") != fragment) return false;
            // Interface/address validation in the client depends on live adapter state.
            if (Text(defaults, "BindInterface").Length != 0 || Text(defaults, "SendThrough").Length != 0
                || !Empty(Read(proxy, "bind_interface")) || !Empty(Read(proxy, "inet4_bind_address")))
            { reason = "unsupported_connection"; return false; }
            reason = "ready";
            return true;
        }
        catch (Exception e) when (e is JsonException or InvalidOperationException or FormatException) { return false; }
    }

    private static JsonElement Read(JsonElement root, string key) =>
        root.ValueKind == JsonValueKind.Object && root.TryGetProperty(key, out var value) ? value : default;
    private static bool UniqueKeys(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.Object => value.EnumerateObject().Select(x => x.Name).Distinct(StringComparer.Ordinal).Count()
            == value.EnumerateObject().Count() && value.EnumerateObject().All(x => UniqueKeys(x.Value)),
        JsonValueKind.Array => value.EnumerateArray().All(UniqueKeys),
        _ => true
    };
    private static string Text(JsonElement root, string key) =>
        Read(root, key) is { ValueKind: JsonValueKind.String } value ? value.GetString() ?? "" : "";
    private static bool Flag(JsonElement root, string key) => Read(root, key).ValueKind == JsonValueKind.True;
    private static bool Empty(JsonElement value) => value.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined
        || value.ValueKind == JsonValueKind.String && string.IsNullOrEmpty(value.GetString())
        || value.ValueKind == JsonValueKind.Array && value.GetArrayLength() == 0;
    private static string[] List(string text) => text.Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
    private static bool SameList(JsonElement value, IEnumerable<string> expected)
    {
        if (Empty(value)) return !expected.Any();
        return value.ValueKind == JsonValueKind.Array && value.EnumerateArray().All(x => x.ValueKind == JsonValueKind.String)
            && value.EnumerateArray().Select(x => x.GetString()!).SequenceEqual(expected, StringComparer.Ordinal);
    }
}
